"""Generate a sequence of values and histogram it, both on the GPU.

Usage: uv run main.py <params-file>

The params file holds one line: "<count> <seed> <bins>".
"""

import sys

import wgpu

WORKGROUP_SIZE = 256

# Value generation and binning, run once per invocation i on the GPU.
# All intermediates fit in i32 (see BRIEF: largest is a*a + a*37 + 11 < 1.6e9).
SHADER = """
struct Params {
    count: u32,
    seed: u32,
    bins: u32,
    pad: u32,
}

@group(0) @binding(0) var<uniform> params: Params;
@group(0) @binding(1) var<storage, read_write> hist: array<atomic<u32>>;

@compute @workgroup_size(%(workgroup)d)
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {
    let i = i32(gid.x);
    if (gid.x >= params.count) {
        return;
    }

    let seed = i32(params.seed);
    let a = ((i %% 40000) * 1597 + seed + 51749) %% 40000;
    let b = (a * a + a * 37 + 11) %% 40009;
    let c = (b * 613 + 7919) %% 40009;
    let d = (c + (i / 40000) * 7919) %% 40009;
    let value = d %% 1000;

    let bin = u32(value) * params.bins / 1000u;
    atomicAdd(&hist[bin], 1u);
}
""" % {"workgroup": WORKGROUP_SIZE}


def read_params(path):
    with open(path) as f:
        count, seed, bins = (int(x) for x in f.read().split())
    return count, seed, bins


def histogram(count, seed, bins):
    adapter = wgpu.gpu.request_adapter_sync(power_preference="high-performance")
    device = adapter.request_device_sync()

    module = device.create_shader_module(code=SHADER)

    params = device.create_buffer_with_data(
        data=bytes(
            memoryview(
                bytes(0)
                + count.to_bytes(4, "little")
                + seed.to_bytes(4, "little")
                + bins.to_bytes(4, "little")
                + (0).to_bytes(4, "little")
            )
        ),
        usage=wgpu.BufferUsage.UNIFORM,
    )
    hist = device.create_buffer_with_data(
        data=bytes(4 * bins),
        usage=wgpu.BufferUsage.STORAGE | wgpu.BufferUsage.COPY_SRC,
    )
    readback = device.create_buffer(
        size=4 * bins,
        usage=wgpu.BufferUsage.MAP_READ | wgpu.BufferUsage.COPY_DST,
    )

    pipeline = device.create_compute_pipeline(
        layout="auto",
        compute={"module": module, "entry_point": "main"},
    )
    layout = pipeline.get_bind_group_layout(0)
    bind_group = device.create_bind_group(
        layout=layout,
        entries=[
            {"binding": 0, "resource": {"buffer": params, "offset": 0, "size": params.size}},
            {"binding": 1, "resource": {"buffer": hist, "offset": 0, "size": hist.size}},
        ],
    )

    groups = (count + WORKGROUP_SIZE - 1) // WORKGROUP_SIZE
    encoder = device.create_command_encoder()
    compute = encoder.begin_compute_pass()
    compute.set_pipeline(pipeline)
    compute.set_bind_group(0, bind_group)
    compute.dispatch_workgroups(groups)
    compute.end()
    encoder.copy_buffer_to_buffer(hist, 0, readback, 0, 4 * bins)
    device.queue.submit([encoder.finish()])

    readback.map_sync(wgpu.MapMode.READ, 0, 4 * bins)
    data = bytes(readback.read_mapped())
    readback.unmap()

    return [int.from_bytes(data[4 * k : 4 * k + 4], "little") for k in range(bins)]


def main(argv):
    count, seed, bins = read_params(argv[1])
    counts = histogram(count, seed, bins)

    lines = [f"BIN {index} {n}" for index, n in enumerate(counts)]
    lines.append(f"TOTAL {count}")
    sys.stdout.write("\n".join(lines) + "\n")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

